The list is 5 → 10 → 15 → 20 and f(head) is called. What is printed?
```c
struct node { int data; struct node *next; };
void f(struct node *p) {
    if (p == NULL) return;
    f(p->next);
    printf("%d ", p->data);
}
```

What does the following function do to a singly linked list?
```c
struct node *f(struct node *head) {
    struct node *prev = NULL, *nxt;
    while (head != NULL) {
        nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}
```

The list is 11 → 22 → 33 → 44 → 55 → 66 and head points to 11. After the code below runs, what does traversing the list from head print?
```c
p = head;
while (p != NULL && p->next != NULL) {
    p->next = p->next->next;
    p = p->next;
}
```

Starting with an empty queue, 5 elements are enqueued and then 2 are dequeued. What happens on the next call enqueue(9)?
```c
#define MAX 5
int q[MAX], front = -1, rear = -1;
void enqueue(int x) {
    if (rear == MAX - 1) { printf("Overflow"); return; }
    if (front == -1) front = 0;
    q[++rear] = x;
}
int dequeue(void) {
    if (front == -1 || front > rear) { printf("Underflow"); return -1; }
    return q[front++];
}
```

Starting with an empty queue, the calls enq(10), enq(20), enq(30), enq(40), deq(), deq(), enq(50), enq(60) are made. What are the final values of front and rear?
```c
#define N 5
int q[N], front = -1, rear = -1;
void enq(int x) {
    if ((rear + 1) % N == front) { printf("Full"); return; }
    if (front == -1) front = 0;
    rear = (rear + 1) % N;
    q[rear] = x;
}
int deq(void) {
    int x = q[front];
    if (front == rear) front = rear = -1;
    else front = (front + 1) % N;
    return x;
}
```

